import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin","description":"学习 too 与 enough 的位置，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin","description":"学习 too 与 enough 的位置，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 too 与 enough 的位置，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 25 The Cutty Sark","link":"/life/english/new-concept/book-3/unit-02/lesson-025"},"next":{"text":"第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy","link":"/life/english/new-concept/book-3/unit-02/lesson-027"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 25 The Cutty Sark","link":"/life/english/new-concept/book-3/unit-02/lesson-025"},"next":{"text":"第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy","link":"/life/english/new-concept/book-3/unit-02/lesson-027"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-026.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-026.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-026.md"};function l(s,e,r,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-26-wanted-a-large-biscuit-tin" tabindex="-1">第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin <a class="header-anchor" href="#第三册-培养技能-·-lesson-26-wanted-a-large-biscuit-tin" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以物品征集与尺寸要求为主题，练习把需求写得可执行。一个“够大”的容器必须说明用来做什么，别人才能判断是否合适。学习 too 与 enough 的位置和逻辑，用简短句子表达过大、过小或足够，而不让否定范围产生歧义。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>container</td><td>/kənˈteɪnə/</td><td>n.</td><td>容器</td><td>an airtight container</td></tr><tr><td>lid</td><td>/lɪd/</td><td>n.</td><td>盖子</td><td>a tight lid</td></tr><tr><td>capacity</td><td>/kəˈpæsəti/</td><td>n.</td><td>容量</td><td>storage capacity</td></tr><tr><td>fit</td><td>/fɪt/</td><td>v.</td><td>容纳或适合</td><td>fit inside</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make room for — 腾出空间容纳</li><li>in good condition — 状态良好</li></ul><h2 id="语法讲解-too-与-enough-的位置" tabindex="-1">语法讲解：too 与 enough 的位置 <a class="header-anchor" href="#语法讲解-too-与-enough-的位置" aria-label="Permalink to &quot;语法讲解：too 与 enough 的位置&quot;">​</a></h2><p>too 加形容词再加 to do，通常表示程度过高以至于不能或不宜完成某动作。形容词加 enough 再加 to do 表示达到所需程度，而 enough 放在名词前，如 enough space。需要说明动作执行者时可在不定式前加 for someone。not large enough 与 too small 常在特定目的下近义，但不等于所有语境都能互换。too pleased to help 等固定语气还可能表达非常乐意，因此解释时应结合形容词意义和实际语境。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The tin is wide enough to hold the cards, but it is too shallow for the wooden pieces.</p></blockquote><p>这个盒子宽到足以装下卡片，但对于木制部件来说太浅。</p><p>enough 在 wide 后；too 在 shallow 前；两个评价分别针对不同物品。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>enough wide 应为 wide enough；wide enough space 则应根据所指改写为 enough space 或 a sufficiently wide space。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 wide enough 和 enough room，检查 enough 的位置；在示范中突出 tallest 与 upright 以传达核心条件。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We need a box for twenty model parts. It must be deep enough to hold the tallest piece upright. A used box is fine if the lid closes securely.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写容器征集说明，明确用途、尺寸条件和状态。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>需求围绕可检验功能，避免空泛地只说 large。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：We need ___ room for two boxes.（enough/too）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> enough</p><p><strong>解析：</strong> enough 放名词前表示足够数量。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把 too small 改成含 enough 的近义表达。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> not large enough</p><p><strong>解析：</strong> 在容纳同一物品的语境中表达未达要求。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句盒子不能装木块的原因是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 太浅。</p><p><strong>解析：</strong> shallow 说明深度不足，不是宽度不足。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：too 与 enough 的位置。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-025">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-027">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",l]]);export{p as __pageData,g as default};
